    server_version='Huddle'
    def log_message(self,*a): pass
    def sendj(self,code,obj):
        b=json.dumps(obj).encode(); self.send_response(code); self.send_header('Content-Type','application/json'); self.send_header('Content-Length',str(len(b))); self.end_headers(); self.wfile.write(b)
    def body(self):
        try:
            n=int(self.headers.get('Content-Length','0')); x=json.loads(self.rfile.read(n) or b'{}'); return x if isinstance(x,dict) else None
        except: return None
    def do_GET(self):
        p=self.path.split('?')[0]; q=self.path.split('?',1)[1] if '?' in self.path else ''
        if p=='/api/health': return self.sendj(200,{'status':'ok','node_id':NODE})
        if p.startswith('/api/ws'): return self.websocket()
        u=auth(self.headers)
        if not u: return self.sendj(401,{'error':'unauthorized'})
        c=conn()
        try:
            if p=='/api/auth/me': return self.sendj(200,{'user':user(u)})
            m=re.match(r'^/api/channels/(\d+)/messages$',p)
            if m:
                cid=int(m.group(1)); ch=c.execute('SELECT * FROM channels WHERE id=?',(cid,)).fetchone()
                if not ch:return self.sendj(404,{'error':'not found'})
                if not c.execute('SELECT 1 FROM channel_members WHERE channel_id=? AND user_id=?',(cid,u['id'])).fetchone():return self.sendj(403,{'error':'forbidden'})
                rs=c.execute('SELECT * FROM messages WHERE channel_id=? AND parent_id IS NULL AND deleted=0 ORDER BY id DESC',(cid,)).fetchall()
                return self.sendj(200,{'messages':[msg(c,r) for r in rs],'next_cursor':None})
            m=re.match(r'^/api/messages/(\d+)/replies$',p)
            if m:
                r=c.execute('SELECT * FROM messages WHERE id=?',(int(m.group(1)),)).fetchone()
                if not r:return self.sendj(404,{'error':'not found'})
                rs=c.execute('SELECT * FROM messages WHERE parent_id=? AND deleted=0 ORDER BY id',(r['id'],))
                return self.sendj(200,{'replies':[msg(c,x) for x in rs],'next_cursor':None})
            m=re.match(r'^/api/workspaces/([^/]+)$',p)
            if m:
                w=c.execute('SELECT * FROM workspaces WHERE slug=?',(m.group(1),)).fetchone()
                if not w:return self.sendj(404,{'error':'not found'})
                if not c.execute('SELECT 1 FROM members WHERE workspace_id=? AND user_id=?',(w['id'],u['id'])).fetchone():return self.sendj(403,{'error':'forbidden'})
                cs=c.execute('SELECT * FROM channels WHERE workspace_id=? AND is_archived=0',(w['id'],)).fetchall()
                return self.sendj(200,{'workspace':dict(w),'channels':[channel(x) for x in cs],'read_state':[]})
            if p=='/api/workspaces':
                ws=c.execute('SELECT w.* FROM workspaces w JOIN members m ON m.workspace_id=w.id WHERE m.user_id=?',(u['id'],)).fetchall(); return self.sendj(200,{'workspaces':[dict(x) for x in ws]})
            m=re.match(r'^/api/channels/(\d+)/members$',p)
            if m:
                rs=c.execute('SELECT u.* FROM users u JOIN channel_members cm ON cm.user_id=u.id WHERE cm.channel_id=?',(int(m.group(1)),)).fetchall(); return self.sendj(200,{'members':[user(x) for x in rs]})
            return self.sendj(404,{'error':'not found'})
